// The bundled scene gallery (generated by scripts/build_gallery.py).

import type { Gallery, GalleryScene } from "../../core/types.ts";
import { normalize } from "../../ds/ui.ts";

const GALLERY_URL = new URL("./gallery/gallery.json", import.meta.url);

let galleryPromise: Promise<Gallery> | undefined;

/** Load gallery.json once; a failed load is retried on the next call. */
export const loadGallery = (): Promise<Gallery> =>
  (galleryPromise ??= fetch(GALLERY_URL)
    .then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json() as Promise<Gallery>;
    })
    .catch((err) => {
      galleryPromise = undefined;
      throw err;
    }));

// Served by Home Assistant (not the dev harness): pictures.py answers with the Hue app's
// picture of the scene where it has one, else with the bundled tile.
const IN_HA = new URL(import.meta.url).pathname.startsWith("/hue_studio_static/");

/** A gallery scene's picture. */
export const thumbUrl = (id: string): string =>
  IN_HA ? `/api/hue_studio/gallery/${id}.jpg` : new URL(`./gallery/thumb/${id}.jpg`, import.meta.url).href;

/**
 * Gallery scene of a bridge scene: by the Hue app picture id (survives renaming), else
 * by name (e.g. "Read", "Ocean dawn") for pictures whose id we do not know yet.
 */
export function galleryMatch(
  gallery: Gallery | null,
  name: string | undefined,
  image?: string | null,
): GalleryScene | null {
  if (!gallery) return null;
  if (image) {
    const byImage = gallery.scenes.find((s) => s.public_image === image);
    if (byImage) return byImage;
  }
  if (!name) return null;
  const n = normalize(name);
  return gallery.scenes.find((s) => normalize(s.name) === n) || null;
}
